// Studies Data - Complete dataset for all study detail pages

export interface StudyDetailData {
  slug: string;
  id: string;
  categoryId: string;
  category: string;
  categoryColor: string;
  title: string;
  excerpt: string;
  date: string;
  readTime: string;
  journal: string;
  imageUrl: string;
  keywords?: string[]; // Optional: Keyword tags for each study
  
  // Researchers
  researchers: Array<{
    name: string;
    role: string;
  }>;
  
  // Institutions
  institutions: string[];
  
  // Summary
  summary: string;
  
  // Execution Protocol
  executionProtocol: Array<{
    title: string;
    desc: string;
  }>;
  
  // Systematic Analysis Sections
  researchObjective: string;
  methodology: {
    intro: string;
    points: string[];
  };
  observations: string[];
  impact: string;
  constraints: string;
  
  // Original Source
  source: {
    title: string;
    doi: string;
    link?: string;  // Original source URL
  };
}

