// Keyword extraction utility - generates relevant keywords from study data
export function getStudyKeywords(study: StudyDetailData): string[] {
  if (study.keywords && study.keywords.length > 0) {
    return study.keywords;
  }
  
  // Generate keywords based on category and title
  const keywordMap: Record<string, string[]> = {
    'Sleep': ['Circadian Rhythm', 'Melatonin', 'REM Sleep', 'Sleep Quality'],
    'Neuroscience': ['Brain Plasticity', 'Neural Pathways', 'Cognition', 'Synapses'],
    'Nutrition': ['Micronutrients', 'Gut Health', 'Metabolism', 'Diet'],
    'Longevity': ['Aging', 'NAD+', 'Autophagy', 'Telomeres'],
    'Metabolism': ['Insulin', 'Energy', 'Thermogenesis', 'Metabolic Rate'],
    'Biochemistry': ['Enzymes', 'Proteins', 'Oxidation', 'Cellular Function'],
    'Genetics': ['DNA', 'Epigenetics', 'Gene Expression', 'Methylation'],
    'Performance': ['Exercise', 'Recovery', 'Strength', 'Endurance'],
    'Physiology': ['Cardiovascular', 'Respiratory', 'Endocrine', 'Body Systems'],
    'Cognition': ['Memory', 'Focus', 'Learning', 'Decision Making'],
    'Behavior': ['Habits', 'Motivation', 'Psychology', 'Behavioral Change'],
    'Technology': ['Digital Health', 'Wearables', 'Screen Time', 'Blue Light'],
    'Aesthetics': ['Skin Health', 'Body Composition', 'Anti-aging', 'Appearance'],
  };
  
  // Title-based keyword extraction
  const titleKeywords: string[] = [];
  const titleLower = study.title.toLowerCase();
  
  if (titleLower.includes('melatonin')) titleKeywords.push('Melatonin');
  if (titleLower.includes('sleep')) titleKeywords.push('Sleep');
  if (titleLower.includes('rem')) titleKeywords.push('REM Sleep');
  if (titleLower.includes('circadian')) titleKeywords.push('Circadian Rhythm');
  if (titleLower.includes('dopamine') || titleLower.includes('dopaminergic')) titleKeywords.push('Dopamine');
  if (titleLower.includes('cortisol')) titleKeywords.push('Cortisol');
  if (titleLower.includes('insulin')) titleKeywords.push('Insulin');
  if (titleLower.includes('nad+') || titleLower.includes('nad ')) titleKeywords.push('NAD+');
  if (titleLower.includes('autophagy')) titleKeywords.push('Autophagy');
  if (titleLower.includes('fasting') || titleLower.includes('caloric restriction')) titleKeywords.push('Fasting');
  if (titleLower.includes('exercise') || titleLower.includes('training')) titleKeywords.push('Exercise');
  if (titleLower.includes('magnesium')) titleKeywords.push('Magnesium');
  if (titleLower.includes('omega') || titleLower.includes('fatty acid')) titleKeywords.push('Omega-3');
  if (titleLower.includes('polyphenol')) titleKeywords.push('Polyphenols');
  if (titleLower.includes('fiber')) titleKeywords.push('Fiber');
  if (titleLower.includes('brain')) titleKeywords.push('Brain Health');
  if (titleLower.includes('stress')) titleKeywords.push('Stress');
  if (titleLower.includes('depression')) titleKeywords.push('Mental Health');
  if (titleLower.includes('memory') || titleLower.includes('hippocampal')) titleKeywords.push('Memory');
  if (titleLower.includes('neuroplasticity')) titleKeywords.push('Neuroplasticity');
  if (titleLower.includes('mitochondri')) titleKeywords.push('Mitochondria');
  if (titleLower.includes('telomere')) titleKeywords.push('Telomeres');
  if (titleLower.includes('crispr')) titleKeywords.push('Gene Editing');
  if (titleLower.includes('methylation')) titleKeywords.push('Epigenetics');
  if (titleLower.includes('glucose') || titleLower.includes('glycemic')) titleKeywords.push('Blood Sugar');
  if (titleLower.includes('thermogenesis') || titleLower.includes('brown fat')) titleKeywords.push('Thermogenesis');
  if (titleLower.includes('liver')) titleKeywords.push('Liver Health');
  if (titleLower.includes('gut') || titleLower.includes('microbiota')) titleKeywords.push('Gut Microbiome');
  if (titleLower.includes('adolescent')) titleKeywords.push('Adolescent Health');
  if (titleLower.includes('light exposure')) titleKeywords.push('Light Therapy');
  if (titleLower.includes('blue light')) titleKeywords.push('Blue Light');
  
  // Combine category keywords with title-specific ones
  const categoryKeywords = keywordMap[study.category] || [];
  const combined = [...new Set([...titleKeywords, ...categoryKeywords.slice(0, 2)])];
  
  return combined.slice(0, 4); // Limit to 4 keywords
}

// Generates a deterministic placeholder image URL for studies missing an image
export function getStudyImageUrl(study: { imageUrl: string; slug: string; category: string }): string {
  if (study.imageUrl && study.imageUrl.length > 0) return study.imageUrl;
  // Use slug as seed for deterministic, unique images per study
  return `https://picsum.photos/seed/${encodeURIComponent(study.slug)}/800/450`;
}

