    readTime: "35 min",
    journal: "Frontiers in Psychology",
    imageUrl: "https://picsum.photos/seed/Neuroscience23/800/450",
    keywords: ["meditation", "decision making", "self-control", "emotion regulation", "empathy", "bias"],
