// Utility functions
export const getStudyBySlug = (slug: string): StudyDetailData | undefined => {
  return STUDIES_DATA.find(study => study.slug === slug);
};

export const getStudyById = (id: string): StudyDetailData | undefined => {
  return STUDIES_DATA.find(study => study.id === id);
};

export const getStudiesByCategory = (category: string): StudyDetailData[] => {
  return STUDIES_DATA.filter(study => study.category.toLowerCase() === category.toLowerCase());
};

export const getCategoryColor = (category: string): string => {
  return CATEGORY_COLORS[category] || 'bg-gray-500';
};

// Create a slug from study ID (e.g., "s-1-0" -> find corresponding study)
export const getSlugFromId = (id: string): string | undefined => {
  const study = STUDIES_DATA.find(s => s.id === id);
  return study?.slug;
};
